    const flags = new Set(args.filter((arg) => arg.startsWith("--")));
    const nonFlags = args.filter((arg) => !arg.startsWith("--"));
    const skipApply = flags.has("--no-apply");
    const name = nonFlags.join("_").toLocaleLowerCase();
    migrateNew(name, skipApply);
}
